<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');check_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){try{$q=db()->prepare('INSERT INTO applications(applicant_user_id,application_type,title,description,status,owner_role,current_stage) VALUES(?,?,?,?,\'Submitted\',\'Student\',\'Submitted\')');$q->execute([actor_id(),$_POST['application_type'],$_POST['title'],$_POST['description']]);$id=(int)db()->lastInsertId();db()->prepare('INSERT INTO application_history(application_id,status,stage,remarks,changed_by) VALUES(?,?,?,?,?)')->execute([$id,'Submitted','Submitted','Student submitted application',actor_id()]);$_SESSION['flash']=['success','Application submitted #'.$id];}catch(Throwable $e){$_SESSION['flash']=['danger',$e->getMessage()];}redirect('applications.php');}$q=db()->prepare('SELECT * FROM applications WHERE applicant_user_id=? ORDER BY id DESC');$q->execute([actor_id()]);page_top('Online Application Center');flash();?><div class='card p-4 mb-4'><form method='post' class='row g-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><div class='col-md-3'><select name='application_type' class='form-select'><option>Bonafide</option><option>Certificate</option><option>Leave</option><option>Scholarship</option><option>Internship</option><option>Exam Request</option><option>Academic Correction</option><option>Other</option></select></div><div class='col-md-4'><input name='title' class='form-control' placeholder='Request title' required></div><div class='col-12'><textarea name='description' class='form-control' placeholder='Describe your request' required></textarea></div><div class='col-12'><button class='btn btn-primary'>Submit Request</button></div></form></div><div class='card p-3 table-responsive'><table class='table'><tr><th>ID</th><th>Type</th><th>Title</th><th>Status</th><th>Stage</th><th>Updated</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['id'])?></td><td><?=e($r['application_type'])?></td><td><?=e($r['title'])?></td><td><?=e($r['status'])?></td><td><?=e($r['current_stage'])?></td><td><?=e($r['updated_at'])?></td></tr><?php endforeach;?></table></div><?php page_bottom();
